func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestClamp(t *testing.T) {
	tests := []struct {
		name   string
		value  int
		lower  int
		upper  int
		expect int
	}{
		{name: "below lower", value: -5, lower: 0, upper: 10, expect: 0},
		{name: "above upper", value: 15, lower: 0, upper: 10, expect: 10},
		{name: "within bounds", value: 5, lower: 0, upper: 10, expect: 5},
		{name: "at lower", value: 0, lower: 0, upper: 10, expect: 0},
		{name: "at upper", value: 10, lower: 0, upper: 10, expect: 10},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := clamp(tt.value, tt.lower, tt.upper); got != tt.expect {
				t.Fatalf("clamp(%d, %d, %d) = %d, want %d", tt.value, tt.lower, tt.upper, got, tt.expect)
			}
		})
	}
}

